#!/usr/bin/env python3
"""Run every Ruptura simulation directory generated by ``generate.py``.

    python run.py                                   # run everything under stadler/
    python run.py figure6_sorbent_only_fresh_bed_8bar_523K
    python run.py --rerun -j 4                      # force a rerun with four workers

Set RUPTURA_BIN to use a binary other than ../../../build/ruptura.
"""

from __future__ import annotations

import argparse
import json
import os
import subprocess
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path

ROOT = Path(__file__).resolve().parent
RUPTURA_BINARY = Path(os.environ.get("RUPTURA_BIN", ROOT.parents[2] / "build" / "ruptura")).resolve()


def run_ruptura(directory: Path) -> dict:
    print(f"running {directory.relative_to(ROOT)}", flush=True)
    with (directory / "run.log").open("w") as log:
        result = subprocess.run(
            [str(RUPTURA_BINARY)], cwd=directory, stdout=log, stderr=subprocess.STDOUT, text=True
        )
    return {"directory": directory, "returncode": result.returncode}


def finished(directory: Path) -> bool:
    # A finished breakthrough prints "Final time:"; a mixture prediction only writes its isotherm files.
    log = directory / "run.log"
    if not log.is_file():
        return False
    if json.loads((directory / "simulation.json").read_text())["SimulationType"] == "MixturePrediction":
        return any(directory.glob("component_*.data"))
    return "Final time:" in log.read_text()


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("dirs", nargs="*", type=Path, default=[ROOT])
    parser.add_argument("--rerun", action="store_true", help="rerun simulations that already finished")
    parser.add_argument("-j", "--workers", type=int, default=8)
    arguments = parser.parse_args()

    if not RUPTURA_BINARY.is_file():
        raise SystemExit(f"Ruptura binary not found at {RUPTURA_BINARY}")

    directories = sorted({match.parent.resolve() for path in arguments.dirs for match in path.rglob("simulation.json")})
    if not directories:
        raise SystemExit("no simulation directories found; run generate.py first")

    pending = [directory for directory in directories if arguments.rerun or not finished(directory)]
    skipped = len(directories) - len(pending)
    if skipped:
        print(f"skipping {skipped} finished simulation(s); use --rerun to force")
    if not pending:
        print("nothing to run")
        return

    failures = []
    with ThreadPoolExecutor(max_workers=arguments.workers) as executor:
        futures = {executor.submit(run_ruptura, directory): directory for directory in pending}
        for future in as_completed(futures):
            result = future.result()
            status = "ok" if result["returncode"] == 0 else f"FAILED ({result['returncode']})"
            print(f"{status}: {result['directory'].relative_to(ROOT)}", flush=True)
            if result["returncode"] != 0:
                failures.append(result["directory"])

    print(f"\n{len(pending) - len(failures)}/{len(pending)} simulations completed")
    for directory in failures:
        print(f"  failed: {directory.relative_to(ROOT)}")


if __name__ == "__main__":
    main()
